import itertools
teams = ["Alpha", "Beta", "Gamma", "Delta"]
matches = list(itertools.combinations(teams, 2))
target = {"Alpha": 7, "Beta": 4, "Gamma": 3, "Delta": 1}
opts = {"A": ("Alpha", "Beta"), "B": ("Beta", "Delta"), "C": ("Alpha", "Gamma"), "D": ("Alpha", "Delta")}
answers = set()
for res in itertools.product((0, 1, 2), repeat=len(matches)):  # 0: first wins, 1: second wins, 2: draw
    pts = {t: 0 for t in teams}
    for (a, b), r in zip(matches, res):
        if r == 2:
            pts[a] += 1
            pts[b] += 1
        else:
            pts[a if r == 0 else b] += 3
    if pts == target:
        drawn = {m for m, r in zip(matches, res) if r == 2}
        answers.add("".join(k for k, m in sorted(opts.items()) if m in drawn))
answer = next(iter(answers)) if len(answers) == 1 else None

import itertools
names = ["P", "Q", "R", "S", "T", "U"]
answers = set()
for ages in itertools.permutations([20, 22, 24, 26, 28, 30]):
    a = dict(zip(names, ages))
    if a["P"] != 22 or a["T"] != a["S"] + 6:
        continue
    for order in itertools.permutations(names):  # (order[0], order[1]) = Pair 1, then Pair 2, Pair 3
        if order[0] > order[1] or order[2] > order[3] or order[4] > order[5]:
            continue
        pairs = [order[0:2], order[2:4], order[4:6]]
        s = [a[x] + a[y] for x, y in pairs]
        if s[0] != s[1] + 2 or s[1] != s[2] + 2 or "Q" not in pairs[0]:
            continue
        mate = {x: y for x, y in pairs}
        mate.update({y: x for x, y in pairs})
        if a["Q"] > a[mate["Q"]] and a["R"] == a[mate["R"]] + 4:
            answers.add(a[mate["Q"]])
answer = next(iter(answers)) if len(answers) == 1 else None

