import itertools
teams = ['A', 'B', 'C', 'D']
matches = list(itertools.combinations(teams, 2))
results_found = []
for res in itertools.product(['W', 'L', 'D'], repeat=6):
    pts = {t: 0 for t in teams}
    match_map = {}
    for i, match in enumerate(matches):
        t1, t2 = match
        if res[i] == 'W':
            pts[t1] += 3
            match_map[match] = t1
        elif res[i] == 'L':
            pts[t2] += 3
            match_map[match] = t2
        else:
            pts[t1] += 1
            pts[t2] += 1
            match_map[match] = 'Draw'
    if pts['A'] == 7 and pts['B'] == 4 and pts['C'] == 2 and pts['D'] == 2:
        if match_map[('A', 'D')] == 'A':
            # Who did B beat?
            victims = []
            for m, winner in match_map.items():
                if winner == 'B':
                    victims.append(m[1] if m[0] == 'B' else m[0])
            results_found.append('B' if 'C' in victims else ('C' if 'D' in victims else 'D'))
answers = set(results_found)
answer = next(iter(answers))
